def load_tasks(name):
    tasks = []
    try:
        with open(name) as f:
            for line in f:
                tasks.append(line.strip())
    except FileNotFoundError:
        print("No saved tasks, starting fresh")
    return tasks

print(load_tasks("tasks.txt"))
